// Transcribed from solid-js@2.0.0-rc.3, the prerelease this repository audits.
// This is the **client** entrypoint (`types/client/hydration.d.ts`); the server
// entrypoint's `createStore` pair is a different, looser shape and is pinned by
// the sibling `callback-slot-derived-store-server` fixture.
//
// `NoFn`, the `createStore` and `createOptimisticStore` overload pairs, and the
// `createSignal`/`createOptimistic` overload sets are the declarations this
// fixture's proof depends on and are byte-faithful to
// `types/client/hydration.d.ts:358`, `:419-425`, `:427-430`, `:246-253` and
// `:312-319`; the option objects, `Refreshable`, `NoInfer` and the hydration
// fields are reduced because nothing here reads them back, and a reduced
// *result* cannot create a callback row. Nothing on the argument side is
// loosened -- above all the plain forms' `NoFn<T>` and `Exclude<T, Function>`,
// which are what make an object-typed argument provably not the compute.
type NoFn<T> = T extends Function ? never : T;

export type Store<T> = T;
export type StoreSetter<T> = (next: T) => void;
export type Accessor<T> = () => T;
export type Signal<T> = [Accessor<T>, (next: T) => T];
export type ComputeFunction<Prev, Next extends Prev = Prev> = (previous: Prev) => Next;
export interface StoreOptions {
  name?: string;
  shallow?: boolean;
}
export interface ProjectionOptions {
  name?: string;
  key?: string;
}
export interface SignalOptions<T> {
  name?: string;
  equals?: false | ((previous: T, next: T) => boolean);
}
export interface MemoOptions<T> {
  name?: string;
  equals?: false | ((previous: T, next: T) => boolean);
}

export declare const createStore: {
  <T extends object = {}>(store: NoFn<T> | Store<NoFn<T>>, options?: StoreOptions): [
    get: Store<T>,
    set: StoreSetter<T>
  ];
  <T extends object = {}>(
    fn: (store: T) => void | T | Promise<void | T> | AsyncIterable<void | T>,
    store: NoFn<T> | Store<NoFn<T>>,
    options?: ProjectionOptions
  ): [get: Store<T>, set: StoreSetter<T>];
};

export declare const createOptimisticStore: {
  <T extends object = {}>(store: NoFn<T> | Store<NoFn<T>>): [get: Store<T>, set: StoreSetter<T>];
  <T extends object = {}>(
    fn: (store: T) => void | T | Promise<void | T> | AsyncIterable<void | T>,
    store: NoFn<T> | Store<NoFn<T>>,
    options?: ProjectionOptions
  ): [get: Store<T>, set: StoreSetter<T>];
};

export declare const createOptimistic: {
  <T>(): Signal<T | undefined>;
  <T>(value: Exclude<T, Function>, options?: SignalOptions<T>): Signal<T>;
  <T>(fn: ComputeFunction<undefined | T, T>, options?: SignalOptions<T>): Signal<T>;
};

export declare const createSignal: {
  <T>(): Signal<T | undefined>;
  <T>(value: Exclude<T, Function>, options?: SignalOptions<T>): Signal<T>;
  <T>(fn: ComputeFunction<undefined | T, T>, options?: SignalOptions<T>): Signal<T>;
};

export declare const createMemo: {
  <T>(compute: ComputeFunction<undefined | T, T>, options?: MemoOptions<T>): Accessor<T>;
};
